from author import C,S,P,V
c=C('特征值与相似对角化')
S(c,'寻找只伸缩而不偏离的方向',[
 P('让几支箭头同时经过这个矩阵。多数箭头会改变所在的直线，但沿右上方向的蓝色箭头，只是变长了，仍在原来那条直线上。如果一个非零向量经过 A 以后，等于它自身乘某个数，这个数叫特征值，向量叫对应的特征向量。负的特征值会反向，零特征值会把它压到原点，所以不是所有情况都只是保持箭头朝向。',V('eigen',A=[[2,1],[1,2]],phase='directions'),[r'A\mathbf{v}=\lambda\mathbf{v}',r'\mathbf{v}\ne0'],['特征向量必须非零','特征值可正、可负、也可为零'],12),
 P('本例一和一组成的向量，变成三和三，所以特征值是三。另一条对角方向，一和负一经过变换后保持原值，特征值是一。同一特征方向上的任意非零倍数，也还是对应特征向量，长度不是唯一的。零向量不能作为特征向量，否则任何数都能满足等式，就失去了识别特殊方向的作用。',V('eigen',A=[[2,1],[1,2]],phase='eigenvectors'),[r'A(1,1)^T=3(1,1)^T',r'A(1,-1)^T=(1,-1)^T'],['两条特征方向对应三与一','特征向量长度可以自由缩放'],12)],['5.2-特征值向量定义'])
S(c,'先解特征值，再解特征向量',[
 P('把特征等式移项，得到 A 减去特征值乘 I，再作用在向量上等于零。因为需要非零向量，这个齐次系统不能只有零解，所以它的行列式必须为零。我们先解这个特征方程。本例主对角元素都是二，展开以后得到，二减特征值的平方再减一，解出特征值一和三。',V('matrix',A=[[2,1],[1,2]],operation='characteristic'),[r'\det(A-\lambda I)=0',r'(2-\lambda)^2-1=0',r'\lambda=1,3'],['非零特征向量对应齐次非零解','先求特征值，再分别代回'],8),
 P('把三代回去，方程要求两个分量相等，可以取一和一。把一代回去，要求两个分量互为相反数，可以取一和负一。这个步骤是在求各自的齐次解空间，不是随意挑一个看起来相近的箭头。算完后，最好把 A 乘向量，与特征值乘向量分别算一遍，检查确实相等。图形能提示答案，但精确等式才是验证。',V('eigen',A=[[2,1],[1,2]],phase='eigenvectors'),[r'\lambda=3:\ \mathbf{v}_1=(1,1)^T',r'\lambda=1:\ \mathbf{v}_2=(1,-1)^T'],['每个特征值分别解一个齐次系统','代回 Av=λv 检查'],10)],['5.2-求特征值与特征向量'])
S(c,'特征值有哪些可核对的关系',[
 P('把所有特征值按重数计算，它们的和等于主对角线元素之和，这个和叫迹；乘积等于行列式。本例三加一等于四，三乘一等于三，分别和矩阵计算吻合。零是特征值，当且仅当矩阵不可逆。不同特征值对应的特征向量线性无关，这是后面能否把它们作为新坐标方向的关键。',V('eigen',A=[[2,1],[1,2]],phase='eigenvectors'),[r'\sum_i\lambda_i=\operatorname{tr}A',r'\prod_i\lambda_i=\det A'],['求和与乘积都按重数计算','不同特征值的特征向量无关'],10),
 P('如果向量属于特征值 λ，那么 A 连做 k 次，就在这个方向上乘 λ 的 k 次方；用矩阵多项式作用，则对应把 λ 代入同一个多项式。A 可逆时，逆矩阵在该方向上的特征值是 λ 的倒数。一般实方阵也可能出现非实特征值，本课演算选用实特征值，讨论实对角化时仍要求有足够的实特征向量，不能只看矩阵元素是实数。',V('eigen',A=[[2,1],[1,2]],phase='powers'),[r'A^k\mathbf{v}=\lambda^k\mathbf{v}',r'p(A)\mathbf{v}=p(\lambda)\mathbf{v}'],['幂与多项式可沿特征方向简化','实对角化要有足够实特征向量'],10)],['5.2-性质与定理'])
S(c,'相似是在另一套坐标里描述',[
 P('同一支箭头，可以用原来的横纵坐标描述，也可以换两支独立箭头作为新坐标方向。把新基向量放成 P 的列，新坐标先乘 P 进入旧坐标，再经过 A，最后乘 P 的逆回到新坐标。因此新矩阵是 P 的逆乘 A 再乘 P。这样的两张矩阵叫相似，它们描述同一个线性作用，只是坐标语言不同。',V('basis',A=[[2,1],[1,2]],phase='change'),[r'B=P^{-1}AP',r'P\text{可逆}'],['先换到旧坐标，再作用，再换回','P 的列是新坐标基'],12),
 P('相似矩阵有相同的特征多项式，所以特征值连同重数相同，迹、行列式和秩也相同。但只有特征值相同，通常不足以反过来断言相似。相似是左右由同一个 P 和它的逆配合，条件比一般矩阵等价严格。不要看见左右都有矩阵相乘，就忽略它们之间必须满足的关系。换坐标也不意味着把实际的线性作用改成另一个作用。',V('matrix',A=[[2,1],[1,2]],B=[[3,0],[0,1]],operation='similarity'),[r'\det B=\det A,\quad r(B)=r(A)',r'\operatorname{tr}B=\operatorname{tr}A'],['同一作用的不同坐标表达','特征值相同并非充分的相似判据'],8)],['5.1-相似定义与性质'])
S(c,'什么时候能得到对角矩阵',[
 P('如果恰好找到 n 个线性无关的特征向量，把它们作为新坐标方向，每个方向都只做自己的伸缩，就没有方向之间的混合。于是新矩阵成为对角矩阵，对角线上依次放对应的特征值。列向量的顺序和对角元素必须一一对应。本例把一和一放第一列，就要把特征值三放在第一个对角位置。',V('basis',A=[[2,1],[1,2]],phase='diagonal'),[r'P^{-1}AP=\Lambda',r'AP=P\Lambda'],['n 个无关特征向量构成 P','特征值顺序与 P 的列一致'],12),
 P('能找到 n 个线性无关特征向量，是可对角化的充要条件。在所讨论的数域里，有 n 个不同特征值，是方便的充分条件，却不是必要条件，单位矩阵只有一种特征值也可对角化。反例是图里的上三角矩阵，它只有特征值一，却只有一个独立特征方向，不能对角化。重根时，要检查特征空间维数，不能只数不同特征值。',V('eigen',A=[[1,1],[0,1]],phase='defective'),[r'J=[\,1,1;0,1\,]',r'\dim\ker(J-I)=1<2'],['重根不自动代表不能对角化','缺少独立特征向量才是关键'],10)],['5.3-判定定理与推论','5.3-矩阵对角化'])
S(c,'练习：算对方向和倍率',[
 P('矩阵还是主对角线为二、另外两个元素为一。向量是一和负一，请判断它是不是特征向量，如果是，对应特征值是多少。再思考，它和一、一组成的向量，能否一起作为对角化使用的新基。建议先真正做一次矩阵乘法，不要因为两个向量长度看起来一样，就给出相同的特征值。',V('matrix',A=[[2,1],[1,2]],vector=[1,-1],operation='question'),[r'\mathbf{v}=(1,-1)^T',r'A\mathbf{v}\ ?'],['先算 Av，再比较 v','独立性与长度不是同一回事'],0)],['5-练习'],kind='question',answer='是特征向量，特征值为1；它与(1,1)线性无关，可作为对角化的新基。')
S(c,'答案：一条不变，一条放大',[
 P('矩阵乘上它，仍得到一和负一，因此对应特征值是一。另一支一和一对应特征值三。两支不共线，所以线性无关，可以一起构成新基。放到 P 的列里面，就能把 A 化为对应顺序的对角矩阵。它们的长度相同并不是关键，决定倍率的是 A 作用在各自方向上的具体结果。',V('eigen',A=[[2,1],[1,2]],phase='eigenvectors'),[r'\lambda_1=3,\quad\lambda_2=1'],['两条独立的特征方向','顺序决定对角线的排列'],10),
 P('这个例子还有一个额外的好处，两支特征向量正好垂直。把它们都缩成单位长度后，换坐标时可以保持长度和夹角。这不是任意可对角化矩阵都自动具有的性质，而和本例矩阵对称有关。下一章先把垂直、投影和正交化的计算补齐，再解释实对称矩阵为什么能使用这样整齐的坐标。',V('basis',A=[[2,1],[1,2]],phase='orthogonal'),[r'(1,1)\cdot(1,-1)=0'],['本例还具有正交结构','下一步：内积、投影与正交化'],10)],['5-练习答案'])

c=C('内积与正交变换')
S(c,'用内积计算长度和夹角',[
 P('两个实向量对应分量相乘再相加，得到一个数，叫内积。一个向量与自身做内积，等于长度的平方；所以长度是这个数的非负平方根。两个非零向量的内积还等于长度乘积再乘夹角的余弦。这里一和一、以及一和负一的内积为零，图上对应两支互相垂直的箭头。',V('projection',u=[1,1],v=[1,-1],phase='orthogonal'),[r'\mathbf{u}\cdot\mathbf{v}=\sum_i u_iv_i',r'\|\mathbf{u}\|=\sqrt{\mathbf{u}\cdot\mathbf{u}}'],['内积给出一个数','非零向量内积为零表示垂直'],10),
 P('实向量内积满足交换、对加法分配，以及非零向量与自身内积严格为正。零向量与任何向量的内积都是零，但它没有确定方向，所以讨论两个方向之间的夹角时，要先排除零向量。把一个非零向量除以自己的长度，就得到同方向的单位向量。单位是长度为一的意思，不是说每个分量都要等于一。',V('vectors',u=[1,1],phase='scale',factor=0.7071067811865476),[r'\mathbf{e}=\frac{\mathbf{u}}{\|\mathbf{u}\|}',r'\|\mathbf{e}\|=1'],['内积的交换、分配与正性','单位化之前长度必须非零'],8)],['5.4-内积及性质','5.4-单位向量'])
S(c,'把一个方向上的部分减掉',[
 P('把橙色向量投影到蓝色向量所在直线上，就是寻找它沿蓝色方向的那一部分。投影系数等于两者内积，除以蓝色向量与自己的内积。这里蓝色是一和一，橙色是一和零，系数是一半，所以投影是二分之一和二分之一。分母不是蓝色的长度，而是长度的平方，这一点很容易记错。',V('projection',u=[1,1],v=[1,0],phase='project'),[r'\operatorname{proj}_{\mathbf{u}}\mathbf{v}',r'=\frac{\mathbf{v}\cdot\mathbf{u}}{\mathbf{u}\cdot\mathbf{u}}\mathbf{u}'],['投影取出沿指定方向的部分','分母是长度的平方'],12),
 P('再把投影从橙色向量里减掉，剩下二分之一和负二分之一。它与蓝色的内积为零，因此正好垂直。图中原箭头被拆成沿着直线的一段和垂直直线的一段。这个减投影的过程，是正交化最核心的动作。它不是随意旋转一个箭头，而是在保持原来张成范围的同时，去掉已经由旧方向表示的那一部分。',V('projection',u=[1,1],v=[1,0],phase='residual'),[r'\mathbf{w}=\mathbf{v}-\operatorname{proj}_{\mathbf{u}}\mathbf{v}',r'\mathbf{u}\cdot\mathbf{w}=0'],['原向量等于投影加垂直剩余','减掉旧方向，保留新信息'],12)],['5.4-施密特正交化基础'])
S(c,'施密特正交化一步步进行',[
 P('施密特正交化从一组线性无关向量开始。第一支先保留；第二支减去在第一支上的投影；第三支再减去在前面所有已得到的正交方向上的投影。这里前两支处理后，得到一和一，以及二分之一和负二分之一。每一步都把旧方向的成分减掉，剩下互相垂直的新方向。',V('projection',u=[1,1],v=[1,0],phase='gram'),[r'\mathbf{w}_k=\mathbf{a}_k-\sum_{i<k}',r'\frac{\mathbf{a}_k\cdot\mathbf{w}_i}{\mathbf{w}_i\cdot\mathbf{w}_i}\mathbf{w}_i'],['依次减去所有已有方向的投影','输入无关时，剩余向量非零'],12),
 P('最后把每支非零结果除以长度，就得到单位正交向量组。如果中途剩余变成零，说明当前向量已经落在前面的张成范围里，不能继续除以它的长度。对于原本线性无关的输入，这种精确计算中的零不会出现。正交化没有改变原来的活动范围，只是换了一组更容易计算长度、夹角和坐标的基。',V('basis',phase='orthogonal'),[r'\mathbf{q}_1=\frac1{\sqrt2}(1,1)^T',r'\mathbf{q}_2=\frac1{\sqrt2}(1,-1)^T'],['得到正交组后再单位化','张成范围保持不变'],10)],['5.4-施密特与单位正交组'])
S(c,'正交矩阵与实对称矩阵',[
 P('把一组单位正交向量放成方阵的列，得到正交矩阵 Q。列之间内积为零，列与自身内积为一，所以 Q 的转置乘 Q 等于 I，因此它的逆就是转置。用这样的矩阵换坐标，不会改变长度和夹角；几何上可以包括旋转，也可能包括镜像反射，并不是所有正交矩阵都只表示旋转。',V('basis',phase='orthogonal'),[r'Q^TQ=I,\quad Q^{-1}=Q^T',r'\|Q\mathbf{x}\|=\|\mathbf{x}\|'],['列向量单位正交','正交变换保持长度和夹角'],10),
 P('实对称矩阵总能选出一组单位正交的实特征向量，使 Q 的转置乘 A 再乘 Q 成为实对角矩阵。不同特征值的特征向量互相正交；同一特征值内部也能选择正交基。本例两条对角方向单位化后，就把矩阵化成对角线上三和一。实对称是重要条件，不能把这个结论原样搬给任意实方阵。',V('basis',A=[[2,1],[1,2]],phase='diagonal'),[r'A=A^T\Rightarrow Q^TAQ=\Lambda',r'\Lambda=\operatorname{diag}(3,1)'],['实对称矩阵可正交对角化','重特征值内部也可正交化'],12)],['5.4-正交矩阵性质','5.4-实对称正交对角化'])
S(c,'练习：正交需要单位长度吗',[
 P('向量一和一，与一和负一，彼此垂直。如果直接把它们作为两列，得到的矩阵就是正交矩阵吗？请区别一组向量互相正交，和一张方阵是正交矩阵这两句话。你可以算每列与自己的内积，检查转置乘自身，得到的是 I 还是别的矩阵。请独立思考四秒。',V('matrix',A=[[1,1],[1,-1]],operation='question'),[r'P^TP\ ?'],['既要互相垂直，也要检查长度','正交矩阵的列必须单位正交'],0)],['5.4-练习'],kind='question',answer='不是；PᵀP=2I。两列分别除以√2后才得到正交矩阵。')
S(c,'答案：还要分别缩成单位长度',[
 P('不是。两列内积为零，但各自长度都是根号二，所以转置乘自身得到二倍 I。把每一列都除以根号二，列与自身内积才成为一，得到真正的正交矩阵。这里不是把垂直性否定了，而是正交矩阵这个名称，还包含了列向量单位长度的要求，两个条件都要满足。',V('basis',phase='normalize'),[r'P^TP=2I',r'Q=\frac1{\sqrt2}P\Rightarrow Q^TQ=I'],['原来的两列正交但不单位','每列除以根号二'],10),
 P('这一章我们从内积判断垂直，用投影拆出分量，再通过减投影与单位化建立整齐的新坐标。对于实对称矩阵，这套坐标还可以取在特征方向上。下面研究二次型时，同样的矩阵会决定一个曲面的形状，而旋转到这些特征方向，就能让混在一起的交叉项消失，公式和图形将再次对应起来。',V('quadratic',A=[[2,1],[1,2]],phase='contour'),[r'Q^TAQ=\operatorname{diag}(3,1)'],['将正交坐标用于二次型','下一步：观察曲面与交叉项'],10)],['5.4-练习答案'])
